package com.example.nativesso.childapp;
import android.app.Activity;import android.content.*;import android.os.Bundle;
import android.util.Log;import android.widget.*;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;import java.util.concurrent.Executors;
public class MainActivity extends Activity{
 private TextView status; private static final int REQ=42;
 @Override public void onCreate(Bundle b){super.onCreate(b);try{CryptoJwt.ensureKey();Log.i("NativeSSO","Child App JWK: "+CryptoJwt.publicJwkString());}catch(Exception ignored){}LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(32,64,32,32);status=new TextView(this);status.setText("Native SSO Child App\n\nTap Sign In to request credentials from the Super App.");Button x=new Button(this);x.setText("Sign In with Native SSO");x.setOnClickListener(v->requestBridge());l.addView(status);l.addView(x);setContentView(l);}
 private void requestBridge(){Intent i=new Intent();i.setClassName("com.example.nativesso.superapp","com.example.nativesso.superapp.CredentialBridgeActivity");i.setAction("com.example.nativesso.GET_CREDENTIALS");startActivityForResult(i,REQ);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r!=REQ||c!=RESULT_OK||d==null){status.setText("Native SSO handoff was rejected or unavailable.");return;}String id=d.getStringExtra("id_token"),ds=d.getStringExtra("device_secret"),proof=d.getStringExtra("dpop_proof");Executors.newSingleThreadExecutor().execute(()->{try{String assertion=CryptoJwt.assertion(SsoConfig.CLIENT_ID,SsoConfig.ISSUER);String body="grant_type="+enc("urn:ietf:params:oauth:grant-type:token-exchange")+"&client_id="+enc(SsoConfig.CLIENT_ID)+"&subject_token="+enc(id)+"&subject_token_type="+enc("urn:ietf:params:oauth:token-type:id_token")+"&actor_token="+enc(ds)+"&actor_token_type="+enc("urn:openid:params:token-type:device-secret")+"&scope="+enc("openid profile email")+"&client_assertion_type="+enc("urn:ietf:params:oauth:client-assertion-type:jwt-bearer")+"&client_assertion="+enc(assertion);String out=Http.post(SsoConfig.TOKEN_ENDPOINT,body,proof);runOnUiThread(()->status.setText("Silent Native SSO succeeded.\n\nToken response:\n"+out));}catch(Exception e){runOnUiThread(()->status.setText("Native SSO exchange failed:\n"+e.getMessage()));}});}
 private static String enc(String s)throws Exception{return URLEncoder.encode(s,StandardCharsets.UTF_8.name());}
}
